('1', '', 'https://images.unsplash.com/photo-1523050854058-8df90110c9f1?w=1600&q=85&auto=format&fit=crop', 'Excellence académique · Foi · Service', 'Campus de l\'Université Adventiste de Lukanga (UNILUK)', 'Vue principale du campus vert de l\'Université Adventiste de Lukanga UNILUK RDC', 'Formation universitaire d\'excellence au cœur de Lukanga', '0', '1'),
('2', '', 'https://images.unsplash.com/photo-1541339907198-e08756dedf3f?w=1600&q=85&auto=format&fit=crop', 'Formation Intégrale · Encadrement de proximité', 'Vie étudiante et enseignement supérieur à Lukanga', 'Étudiants diplômés et enseignants de l\'UNILUK Lukanga réunis sur le campus', 'Une communauté estudiantine dynamique et engagée', '1', '1'),
('3', '', 'https://images.unsplash.com/photo-1562774053-701939374585?w=1600&q=85&auto=format&fit=crop', 'Trois Institutions · Un Campus d\'Avenir', 'Infrastructures et amphis de l\'UNILUK, ISTA et ISTM Lukanga', 'Infrastructures modernes et salles de cours équipées de l\'UNILUK et ISTA Lukanga', 'Infrastructures pédagogiques et scientifiques modernes', '2', '1'),
