INSERT IGNORE INTO core_faculty (`id`, `code`, `name`, `image`, `image_url`, `short_description`, `description`, `programs`, `schedule_file`, `order`, `is_published`) VALUES
('1', 'THEO', 'Faculté de Théologie', '', 'https://images.unsplash.com/photo-1507692049790-de58290a4334?w=700&q=80', 'Formation pastorale et biblique, au service de l\'Église et de la société.', 'La Faculté de Théologie prépare des pasteurs, aumôniers et enseignants de religion enracinés dans les Écritures et engagés dans le service communautaire, avec un solide encadrement pratique en paroisse.', '["Licence en Théologie pastorale","Licence en Sciences religieuses","Stage pastoral encadré","Séminaires bibliques"]', '', '0', '1'),
('2', 'SEG', 'Faculté des Sciences Économiques et de Gestion', '', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=700&q=80', 'Économie, gestion des entreprises, comptabilité et finance appliquée.', 'La Faculté SEG forme des gestionnaires, économistes et comptables capables d\'accompagner le développement des entreprises et institutions publiques congolaises, avec un fort accent sur les cas pratiques et les stages.', '["Gestion financière","Comptabilité & Audit","Économie du développement","Entrepreneuriat"]', '', '1', '1'),
('3', 'SIP', 'Faculté des Sciences Infirmières & Santé Publique', '', 'https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=700&q=80', 'Soins infirmiers, santé communautaire et santé publique.', 'Cette faculté forme des professionnels de santé compétents et empathiques, en lien direct avec la Polyclinique de l\'UNILUK pour une pratique clinique encadrée dès les premières années.', '["Sciences infirmières générales","Santé publique","Nutrition & diététique","Stages cliniques encadrés"]', '', '2', '1'),
('4', 'PED', 'Faculté de Pédagogie Appliquée', '', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?w=700&q=80', 'Sciences de l\'éducation et formation des futurs enseignants.', 'La Faculté de Pédagogie forme des enseignants et cadres éducatifs maîtrisant à la fois les disciplines scientifiques et les méthodes pédagogiques modernes, avec des stages pratiques en écoles partenaires.', '["Pédagogie appliquée","Psychologie de l\'éducation","Didactique des sciences","Stage en école partenaire"]', '', '3', '1'),
('5', 'ISTA', 'Institut Supérieur des Techniques Appliquées (ISTA)', '', 'https://images.unsplash.com/photo-1517430816045-df4b7de11d1d?w=700&q=80', 'Informatique, électromécanique et techniques appliquées.', 'L\'ISTA Lukanga forme des techniciens et ingénieurs de pratique en informatique, électromécanique et technologies appliquées, avec des laboratoires équipés et des projets réels en partenariat avec des entreprises locales.', '["Informatique de gestion","Réseaux & télécommunications","Électromécanique","Projets d\'entreprise"]', '', '4', '1'),
('6', 'ISTM', 'Institut Supérieur des Techniques Médicales (ISTM)', '', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=700&q=80', 'Techniques de laboratoire, imagerie médicale et kinésithérapie.', 'L\'ISTM Lukanga forme des techniciens médicaux hautement qualifiés dans les filières paramédicales, en lien étroit avec la pratique hospitalière régionale.', '["Techniques de laboratoire","Imagerie médicale","Kinésithérapie","Anesthésie-réanimation"]', '', '5', '1');
INSERT IGNORE INTO core_article (`id`, `category`, `category_color`, `title`, `slug`, `image`, `image_url`, `excerpt`, `content`, `published_at`, `order`, `is_published`) VALUES
('1', 'Vie académique', 'bg-sky-600', 'Ouverture officielle de l\'année académique 2026–2027', 'article-1', '', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?w=700&q=80', 'Le recteur a présidé la cérémonie de rentrée devant plus de 1200 nouveaux étudiants.', 'L\'Université Adventiste de Lukanga a procédé à l\'ouverture solennelle de son année académique 2026-2027 en présence des autorités provinciales, des enseignants et de plus de 1200 nouveaux étudiants venus de toute la région du Haut-Lomami.
INSERT IGNORE INTO core_announcement (`id`, `tag`, `color`, `title`, `content`, `published_at`, `attachment`, `order`, `is_published`) VALUES
('1', 'Académique', 'bg-sky-600', 'Calendrier des examens du premier semestre 2026-2027', 'Le Secrétariat Général Académique porte à la connaissance de tous les étudiants que le calendrier des examens du premier semestre est désormais disponible. Les épreuves débuteront le 15 décembre 2026 et se dérouleront selon l\'horaire affiché dans chaque faculté.
INSERT IGNORE INTO core_institution (`id`, `acronym`, `color`, `name`, `image`, `image_url`, `short_description`, `description`, `order`, `is_published`) VALUES
('1', 'UNILUK', 'bg-sky-600', 'Université Adventiste de Lukanga', '', 'https://images.unsplash.com/photo-1592280771190-3e2e4d571952?w=900&q=80', 'L\'institution mère, offrant des formations en théologie, gestion, éducation et santé publique.', 'L\'Université Adventiste de Lukanga est l\'institution fondatrice du campus, offrant des formations de licence et de master dans les domaines de la théologie, des sciences économiques et de gestion, de la pédagogie appliquée et de la santé publique. Fondée sur les valeurs adventistes d\'excellence et de service, elle forme depuis plus de 30 ans des cadres reconnus dans toute la région.', '0', '1'),
('2', 'ISTA', 'bg-sun-500', 'Institut Supérieur des Techniques Appliquées', '', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=900&q=80', 'Formations techniques et technologiques : informatique, électromécanique, réseaux.', 'L\'ISTA Lukanga forme des techniciens supérieurs et ingénieurs de pratique dans les domaines de l\'informatique, de l\'électromécanique et des technologies appliquées. Ses laboratoires modernes et ses partenariats industriels garantissent une formation résolument tournée vers l\'employabilité.', '1', '1'),
('3', 'ISTM', 'bg-emerald-600', 'Institut Supérieur des Techniques Médicales', '', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=900&q=80', 'Formations paramédicales : laboratoire, imagerie médicale, kinésithérapie.', 'L\'ISTM Lukanga prépare des techniciens médicaux qualifiés en laboratoire, imagerie médicale, kinésithérapie et anesthésie-réanimation. Adossé à la Polyclinique de l\'UNILUK, l\'institut garantit un apprentissage clinique concret dès les premiers stages.', '2', '1');
INSERT IGNORE INTO core_studentgroup (`id`, `acronym`, `name`, `icon`, `color`, `image`, `image_url`, `description`, `full_description`, `achievements`, `website`, `contact_email`, `order`, `is_published`) VALUES
('1', 'GACI', 'Groupe des Chercheurs et Analystes en Informatique', 'fa-laptop-code', 'bg-sky-600', '', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=700&q=80', 'Un cercle d\'étudiants passionnés de programmation, cybersécurité et intelligence artificielle.', 'Le GACI rassemble les étudiants de l\'ISTA et de l\'informatique de gestion autour de projets concrets : développement d\'applications, initiation à l\'IA et compétitions de programmation. Le groupe organise des formations hebdomadaires ouvertes à tous les étudiants intéressés par le numérique.', '["1er prix au Hackathon régional du Haut-Lomami 2025","Développement de l\'application interne de gestion des notes","Formation de plus de 150 étudiants en bureautique et code"]', '#', 'gaci@uniluk.ac.cd', '0', '1'),
('2', 'GREG', 'Groupe de Recherche en Économie et Gestion', 'fa-chart-line', 'bg-sun-500', '', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=700&q=80', 'Un espace d\'échange et de recherche pour les étudiants de la Faculté SEG.', 'Le GREG anime des séminaires, publie des notes d\'analyse économique régionale et accompagne les étudiants dans le montage de projets entrepreneuriaux. Il organise chaque année un forum entrepreneurial ouvert aux acteurs économiques de Lukanga.', '["Organisation du Forum Entrepreneurial UNILUK 2025","Publication de 12 notes d\'analyse économique régionale","Incubation de 6 projets étudiants"]', '', 'greg@uniluk.ac.cd', '1', '1'),
('3', 'CACIM', 'Cercle Académique des Cadres en Imagerie Médicale', 'fa-heart-pulse', 'bg-emerald-600', '', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=700&q=80', 'Le cercle des étudiants de l\'ISTM engagés dans la recherche paramédicale.', 'Le CACIM regroupe les étudiants de l\'ISTM autour de journées de sensibilisation sanitaire, de campagnes de dépistage communautaire et d\'ateliers pratiques en imagerie médicale, en lien direct avec la Polyclinique de l\'UNILUK.', '["Campagne de dépistage gratuit auprès de 800 habitants de Lukanga","Atelier annuel d\'imagerie médicale avancée","Partenariat avec l\'Hôpital Général de Kamina"]', '', 'cacim@uniluk.ac.cd', '2', '1');
